private static String normalizePath(final String path) {
    String s = path;
    if (s == null) {
        return null;
    }
    int n = 0;
    for (; n < s.length(); n++) {
        if (s.charAt(n) != '/') {
            break;
        }
    }
    if (n <= 1) {
        return s;
    }
    s = s.substring(n - 1);
    return s;
}
